"""Build the MVP candidate review from real Flutter-navigation captures."""
import argparse,ast,hashlib,html,json,re
from pathlib import Path
root=Path(__file__).resolve().parents[1]
p=argparse.ArgumentParser();p.add_argument('--version',default='0.7.0');p.add_argument('--prototype',type=Path,required=True);a=p.parse_args()
out=root/f'design-baseline/v{a.version}'
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def save(name,data):(out/name).write_text(json.dumps(data,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
old=json.loads((root/'design-baseline/v0.6.2/pages.json').read_text(encoding='utf-8'))
records=[]
for row in old:
 variants=[]
 for mode in ('light','dark','large'):
  file=out/f'screenshots/android/{mode}/{row["id"]}.png';assert file.is_file(),file
  variants.append({'name':mode,'screenshot':file.relative_to(out).as_posix(),'sha256':sha(file)})
 records.append({'id':row['id'],'title':row['title'],'variants':variants,'evidence':'Flutter navigation; synthetic data; English; not a physical device capture','reference':'MVP shared components extension; original Plaud classification is historical'})
save('pages.json',records)
rows=[]
for file in sorted((out/'screens').glob('*.png')):
 platform,locale,mode,name=file.stem.split('-',3)
 rows.append({'id':name,'title':name,'platform':platform,'language':locale,'mode':mode,'screenshot':file.relative_to(out).as_posix(),'sha256':sha(file),'evidence':'Flutter actual navigation; synthetic data'})
for row in records:
 for v in row['variants']:rows.append({'id':row['id'],'title':row['title'],'platform':'android','language':'en','mode':v['name'],'screenshot':v['screenshot'],'sha256':v['sha256'],'evidence':row['evidence']})
save('screenshot-manifest.json',rows)
s=(a.prototype/'data.js').read_text(encoding='utf-8');array=s[s.index('['):s.index('].map')+1];pages=ast.literal_eval(re.sub(r'\bnull\b','None',array))
keys={'home':'01-home','device-menu':'07-device-connect','device-select':'07-device-connect','device-scan':'07-device-connect','device-found':'90-jwd-matches','device-detail':'07-device-connect','notes':'14-recording-notes','transcript':'15-transcript','templates':'53-template-picker','share':'81-export-menu','share-link':'27-share','export':'23-export','more':'48-recording-options','speakers':'49-speaker-names','ask':'19-new-chat','settings':'21-settings','library':'04-library','search':'06-search','import':'26-import','uploads':'59-import-pending','recording':'09-recording','paused':'10-paused','processing':'58-document-processing','failed':'62-processing-failed','share-content':'73-share-content','history':'54-note-versions','language':None,'empty':'39-home-empty','offline':'41-library-offline','login':'25-login','calendar':'28-calendar','files':'72-my-files-views','preferences':'79-transcription-preferences','topics':'14-recording-notes'}
save('prototype-map.json',[{'prototype_id':v[0],'screen':v[1],'title':v[2],'reference_slice':v[4],'kind':'provided slice' if v[4] else 'design extension','regression_state':keys[v[1]],'implementation':'implemented','visual_acceptance':'candidate review; no full 4dp measurement claim','physical_acceptance':'pending' if len(v)>6 else 'not a hardware result'} for v in pages])
source=json.loads((a.prototype/'reference-manifest.json').read_text(encoding='utf-8'));save('design-source.json',source)
css='''*{box-sizing:border-box}body{margin:0;background:#FBFAF6;color:#252C24;font:15px/1.65 system-ui,sans-serif}main{max-width:1240px;margin:auto;padding:24px}h1{font-size:28px}nav{display:flex;gap:10px;flex-wrap:wrap;position:sticky;top:0;background:#FBFAF6;padding:16px 0;z-index:2}select,input,button{font:inherit;padding:10px;border:1px solid #E1E4D9;border-radius:10px;background:white;color:#356448}#grid{display:grid;grid-template-columns:repeat(auto-fill,minmax(210px,1fr));gap:16px}figure{margin:0;padding:12px;background:#F3F4EC;border-radius:14px}figure img{width:100%;height:320px;object-fit:contain;object-position:top;cursor:zoom-in}figcaption{font-size:13px;padding-top:8px}dialog{width:min(94vw,1100px);height:94vh;border:0;border-radius:16px;background:#FBFAF6;color:#252C24}dialog img{width:100%;height:calc(100% - 65px);object-fit:contain}dialog::backdrop{background:#0009}.muted{color:#697064}a{color:#356448}@media(max-width:430px){main{padding:14px}#grid{grid-template-columns:repeat(2,minmax(0,1fr));gap:8px}figure{padding:6px}figure img{height:230px}}'''
data=json.dumps(rows,ensure_ascii=False).replace('</',r'<\/')
page='''<!doctype html><html lang="zh-CN"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Teno MVP 0.7.0 / Web 0.2.0 UI</title><style>CSS</style><main><h1>Teno MVP · 双语候选 UI</h1><p>Android 0.7.0 / 14 · Web 0.2.0 / 5。暖白、鼠尾草绿与深绿主操作；按用户提供的 16 张原图与 34 状态原型实施。</p><p class="muted">481 张 Flutter 页面截图：87 状态 × 3 模式，加 220 张双语与 Web 响应式截图。使用合成资料、实际导航；不是硬件验收。未声称全页 ≤4dp 通过；原生系统画面另见 verification/v0.7.0。实体 Safari / Magic4 Pro / JWD 待验收。</p><p><a href="differences-and-acceptance.txt">差异与验收边界</a> · <a href="prototype-map.json">34 状态映射</a> · <a href="screenshot-manifest.json">全部图片 SHA256</a></p><nav><input id="q" placeholder="搜索页面"><select id="platform"><option value="">全部平台</option><option>android</option><option>web</option></select><select id="language"><option value="">全部语言</option><option>zh</option><option>en</option></select><select id="mode"><option>light</option><option>dark</option><option>large</option><option>tablet</option><option>desktop</option><option>wide</option><option>landscape</option></select><span id="count"></span></nav><div id="grid"></div></main><dialog id="preview"><button id="prev">上一页</button> <button id="next">下一页</button> <button id="close">关闭</button><span id="title"></span><img alt="页面预览"></dialog><script>const rows=DATA;let chosen=[],current=0;const $=s=>document.querySelector(s);function open(i){current=(i+chosen.length)%chosen.length;const r=chosen[current];$('#preview img').src=r.screenshot;$('#title').textContent=r.title+' · '+r.platform+' '+r.language+' '+r.mode;if(!$('#preview').open)$('#preview').showModal()}function render(){chosen=rows.filter(r=>r.title.toLowerCase().includes($('#q').value.toLowerCase())&&['platform','language','mode'].every(k=>!$('#'+k).value||r[k]===$('#'+k).value));$('#count').textContent=chosen.length+' 张';$('#grid').replaceChildren(...chosen.map((r,i)=>{const f=document.createElement('figure'),im=new Image(),c=document.createElement('figcaption');im.src=r.screenshot;im.loading='lazy';im.alt=r.title;im.onclick=()=>open(i);c.textContent=r.title+' · '+r.platform+' '+r.language+' '+r.mode;f.append(im,c);return f}));}document.querySelectorAll('input,select').forEach(e=>e.oninput=render);$('#close').onclick=()=>$('#preview').close();$('#prev').onclick=()=>open(current-1);$('#next').onclick=()=>open(current+1);document.addEventListener('keydown',e=>{if($('#preview').open&&e.key==='ArrowRight')open(current+1);if($('#preview').open&&e.key==='ArrowLeft')open(current-1)});render();</script></html>'''.replace('CSS',css).replace('DATA',data)
(out/'index.html').write_text(page,encoding='utf-8')
print(json.dumps({'states':len(records),'prototype_states':len(pages),'screenshots':len(rows),'all_hashes_verified':True}))
